  protected AbstractCommand(String name, String commandCode) {
    if (name != null) {
      helpText = name + Color.WHITE + " : " + t(commandCode);

      int splitIndex = name.indexOf(" ");
      if (splitIndex != -1) {
        name = name.substring(0, splitIndex);
